input.workflow:
[
  {
    "phase": "Phase 1: Research Collection",
    "parallel": true,
    "tasks": [
      {"agent": "researcher_1", "task": "Conduct comprehensive research on Salt Lake City population health, SDOH factors, and comparative analysis with national data. Document all findings with proper APA citations."},
      {"agent": "researcher_2", "task": "Research evidence-based community health interventions, 10-year outcome studies, and implementation frameworks applicable to SLC's identified vulnerabilities. Document all findings with proper APA citations."}
    ]
  },
  {
    "phase": "Phase 2: Research Quality Gate",
    "parallel": true,
    "tasks": [
      {"agent": "research_qa_1", "task": "Review Researcher 1's work against all quality criteria. Provide PASS or FAIL verdict with detailed feedback."},
      {"agent": "research_qa_2", "task": "Review Researcher 2's work against all quality criteria. Provide PASS or FAIL verdict with detailed feedback."}
    ]
  },
  {
    "phase": "Phase 3: Data Visualization",
    "parallel": true,
    "tasks": [
      {"agent": "data_analyst_1", "task": "Create Chart.js specifications for all Part 1 visualizations: SLC vs National comparisons, SDOH radar charts, disparity charts, trend lines."},
      {"agent": "data_analyst_2", "task": "Create Chart.js specifications for all Part 2 visualizations: 10-year projection charts, cost-benefit analysis, timeline charts, outcome scenarios."}
    ]
  },
  {
    "phase": "Phase 4: Manuscript Writing",
    "parallel": false,
    "tasks": [
      {"agent": "writer_1", "task": "Write Part 1 of the manuscript (Abstract through Discussion first half) using the QA-approved research. End with a clear transition point."},
      {"agent": "writer_2", "task": "Write Part 2 of the manuscript (Discussion second half through References) using the QA-approved research. Begin EXACTLY where Writer 1 ended, matching style perfectly."}
    ]
  },
  {
    "phase": "Phase 5: Writing Quality Gate",
    "parallel": true,
    "tasks": [
      {"agent": "writing_qa_1", "task": "Review Writer 1's manuscript against all quality criteria. Provide PASS or FAIL verdict with detailed feedback."},
      {"agent": "writing_qa_2", "task": "Review Writer 2's manuscript against all quality criteria, with special attention to style consistency with Part 1. Provide PASS or FAIL verdict."}
    ]
  }
]
